import { Node, NodeType } from 'prosemirror-model';
import { EditorState, TextSelection } from 'prosemirror-state';
import { EditorView } from 'prosemirror-view';

let view: { current?: EditorView } = {};
export const addView = (v: EditorView) => (view.current = v);
export const getView = () => view.current;
export default () => '';

export function escapeLatex(latex: string) {
	const escapeMap: Record<string, string> = {
		'\\': '\\\\',
		'{': '\\{',
		'}': '\\}',
		$: '\\$',
		'&': '\\&',
		'#': '\\#',
		_: '\\_',
		'%': '\\%',
		'^': '\\^',
		'~': '\\~'
	};

	return latex.replace(/[\\{}$&#_%^~]/g, (match) => escapeMap[match]);
}

let uniqueIdCounter = 1000;
export function generateUniqueId() {
	uniqueIdCounter++;
	const base36 = uniqueIdCounter.toString(36);
	const randomPart = Math.random().toString(36).substring(2, 4);
	return randomPart + base36;
}

export function assignUniqueId(node: any) {
	if (!node.attrs.id) {
		node.attrs.id = generateUniqueId();
	}
}

export function convertToChineseNumber(num: number): string {
	const units = [
		'',
		'十',
		'百',
		'千',
		'万',
		'十',
		'百',
		'千',
		'亿',
		'十',
		'百',
		'千',
		'万'
	];
	const digits = ['零', '一', '二', '三', '四', '五', '六', '七', '八', '九'];

	if (num === 0) return '零';

	const numStr = num.toString();
	let result = '';
	let zeroFlag = false;

	for (let i = 0; i < numStr.length; i++) {
		const digit = parseInt(numStr[i]);
		const unitPos = numStr.length - i - 1;

		if (digit === 0) {
			zeroFlag = true;
		} else {
			if (zeroFlag) {
				result += '零';
				zeroFlag = false;
			}
			result += digits[digit] + units[unitPos];
		}
	}
	result = result.replace(/^一十/, '十');
	return result.replace(/零+$/, '');
}

export function convertToAlphabet(num: number): string {
	if (num <= 0) return '';

	let result = '';
	while (num > 0) {
		num--;
		result = String.fromCharCode((num % 26) + 97) + result;
		num = Math.floor(num / 26);
	}

	return result;
}

export function convertToRoman(num: number): string {
	const romanNumerals: { [key: number]: string } = {
		1000: 'm',
		900: 'cm',
		500: 'd',
		400: 'cd',
		100: 'c',
		90: 'xc',
		50: 'l',
		40: 'xl',
		10: 'x',
		9: 'ix',
		5: 'v',
		4: 'iv',
		1: 'i'
	};

	let result = '';
	for (const [value, numeral] of Object.entries(romanNumerals).reverse()) {
		while (num >= parseInt(value)) {
			result += numeral;
			num -= parseInt(value);
		}
	}

	return result;
}

export function shallowEqual(obj1: any, obj2: any): boolean {
	if (obj1 === obj2) return true;

	if (
		typeof obj1 !== 'object' ||
		obj1 === null ||
		typeof obj2 !== 'object' ||
		obj2 === null
	) {
		return false;
	}

	const keys1 = Object.keys(obj1);
	const keys2 = Object.keys(obj2);

	if (keys1.length !== keys2.length) {
		return false;
	}

	for (let key of keys1) {
		if (obj1[key] !== obj2[key]) {
			return false;
		}
	}

	return true;
}

export function classnames(
	...args: (string | Record<string, boolean | undefined> | undefined)[]
) {
	return args
		.filter(Boolean)
		.map((item) => {
			if (typeof item === 'string') return item;
			return Object.keys(item!)
				.filter((key) => !!item![key])
				.join(' ');
		})
		.join(' ');
}

export function isNotEmpty(val: any) {
	return !!val || val === 0;
}

export function overrides<T extends Record<string | symbol, any> = any>(
	target: T,
	props: Record<string, any>
) {
	return new Proxy(target, {
		get(target, key) {
			if (typeof key !== 'symbol' && props[key]) return props[key];
			return target[key];
		}
	});
}

export function nextTick(fn?: () => void) {
	const { promise, resolve } = Promise.withResolvers();
	if (requestAnimationFrame) {
		requestAnimationFrame(resolve);
	} else {
		setTimeout(resolve, 17);
	}
	return promise.then(() => fn?.());
}

export function getSelectionRect(view: EditorView) {
	const { selection } = view.state;

	// 获取 DOM 节点和偏移
	const start = view.domAtPos(selection.from);
	const end = view.domAtPos(selection.to);

	// 创建 Range 并设置起点和终点
	const range = document.createRange();
	if (selection.empty) {
		const { node } = start;
		if (node instanceof HTMLElement) return node.getBoundingClientRect();
	}
	range.setStart(start.node, start.offset);
	range.setEnd(end.node, end.offset);

	return range.getBoundingClientRect();
}

export function selectionContainsOnlyText(
	state: EditorState,
	...whitelist: NodeType[]
) {
	const { selection } = state;

	const whitelistNode: Node[] = [];
	// 如果选区不是 TextSelection，直接返回 false
	if (!(selection instanceof TextSelection)) {
		return [false, whitelistNode] as const;
	}

	// 遍历选区范围内的所有节点
	let onlyText = true;
	const { from, to } = selection;
	state.doc.nodesBetween(selection.from, selection.to, (node, pos) => {
		let white = false;
		if (whitelist.includes(node.type)) {
			whitelistNode.push(node);
			white = true;
		}
		if (
			!node.isText &&
			!white &&
			(pos >= Math.min(from, to) || pos + node.nodeSize <= Math.max(from, to))
		) {
			onlyText = false;
			return false;
		}
	});

	return [onlyText, whitelistNode] as const;
}
