import { Node } from 'prosemirror-model';
import { EditorState, PluginKey, Transaction } from 'prosemirror-state';
import { TableRole, tableNodeTypes } from './schema';
import { TableMap } from './tableMap';
import { CellAttrs, removeColSpan } from './utils';
import { createNodeAndFill } from '../../commands';

export const fixTablesKey = new PluginKey<{ fixTables: boolean }>('fix-tables');
function changedDescendants(
	old: Node,
	cur: Node,
	offset: number,
	f: (node: Node, pos: number) => void
): void {
	const oldSize = old.childCount,
		curSize = cur.childCount;
	outer: for (let i = 0, j = 0; i < curSize; i++) {
		const child = cur.child(i);
		for (let scan = j, e = Math.min(oldSize, i + 3); scan < e; scan++) {
			if (old.child(scan) == child) {
				j = scan + 1;
				offset += child.nodeSize;
				continue outer;
			}
		}
		f(child, offset);
		if (j < oldSize && old.child(j).sameMarkup(child))
			changedDescendants(old.child(j), child, offset + 1, f);
		else child.nodesBetween(0, child.content.size, f, offset + 1);
		offset += child.nodeSize;
	}
}

export function fixTables(
	state: EditorState,
	oldState?: EditorState
): Transaction | undefined {
	let tr: Transaction | undefined;
	const check = (node: Node, pos: number) => {
		if (node.type.spec.tableRole == 'table')
			tr = fixTable(state, node, pos, tr);
	};
	if (!oldState) state.doc.descendants(check);
	else if (oldState.doc != state.doc)
		changedDescendants(oldState.doc, state.doc, 0, check);
	return tr;
}

export function fixTable(
	state: EditorState,
	table: Node,
	tablePos: number,
	tr: Transaction | undefined
): Transaction | undefined {
	const map = TableMap.get(table);
	if (!map.problems) return tr;
	if (!tr) tr = state.tr;

	// Track which rows we must add cells to, so that we can adjust that
	// when fixing collisions.
	const mustAdd: number[] = [];
	for (let i = 0; i < map.height; i++) mustAdd.push(0);
	for (let i = 0; i < map.problems.length; i++) {
		const prob = map.problems[i];
		if (prob.type == 'collision') {
			const cell = table.nodeAt(prob.pos);
			if (!cell) continue;
			const attrs = cell.attrs as CellAttrs;
			for (let j = 0; j < attrs.rowspan; j++) mustAdd[prob.row + j] += prob.n;
			tr.setNodeMarkup(
				tr.mapping.map(tablePos + 1 + prob.pos),
				null,
				removeColSpan(attrs, attrs.colspan - prob.n, prob.n)
			);
		} else if (prob.type == 'missing') {
			mustAdd[prob.row] += prob.n;
		} else if (prob.type == 'overlong_rowspan') {
			const cell = table.nodeAt(prob.pos);
			if (!cell) continue;
			tr.setNodeMarkup(tr.mapping.map(tablePos + 1 + prob.pos), null, {
				...cell.attrs,
				rowspan: cell.attrs.rowspan - prob.n
			});
		} else if (prob.type == 'colwidth mismatch') {
			const cell = table.nodeAt(prob.pos);
			if (!cell) continue;
			tr.setNodeMarkup(tr.mapping.map(tablePos + 1 + prob.pos), null, {
				...cell.attrs,
				colwidth: prob.colwidth
			});
		}
	}
	let first, last;
	for (let i = 0; i < mustAdd.length; i++)
		if (mustAdd[i]) {
			if (first == null) first = i;
			last = i;
		}

	for (let i = 0, pos = tablePos + 1; i < map.height; i++) {
		const row = table.child(i);
		const end = pos + row.nodeSize;
		const add = mustAdd[i];
		if (add > 0) {
			let role: TableRole = 'cell';
			if (row.firstChild) {
				role = row.firstChild.type.spec.tableRole;
			}
			const nodes: Node[] = [];
			for (let j = 0; j < add; j++) {
				const node = createNodeAndFill(tableNodeTypes(state.schema)[role]);

				if (node) nodes.push(node);
			}
			const side = (i == 0 || first == i - 1) && last == i ? pos + 1 : end - 1;
			tr.insert(tr.mapping.map(side), nodes);
		}
		pos = end;
	}
	return tr.setMeta(fixTablesKey, { fixTables: true });
}
